def f(g):
    h=len(g); w=len(g[0])
    o=[row[:] for row in g]
    # gap cells: within a horizontal run, isolated 0 flanked by same color on both sides (same color left and right, not necessarily contiguous)
    for i in range(h):
        row=g[i]
        gaps=[]
        j=0
        while j<w:
            if row[j]==0:
                l=j-1; r=j+1
                if l>=0 and row[l]==row[r] and row[l]!=0:
                    c=row[l]
                    gaps.append((i,l,c))
                j+=1
            else: j+=1
        for gi,gc,gc_ in gaps:
            o[gi][gc]=gc_
            k=gi-1
            while k>=0 and o[k][gc]==0:
                o[k][gc]=gc_; k-=1
    return o
