def solve(inp):
    H,W=len(inp),len(inp[0])
    o=[r[:] for r in inp]
    # find gap cells: cell==0 with same nonzero neighbor left&right in same row
    for r in range(H):
        for c in range(W):
            if inp[r][c]==0 and c>0 and c<W-1 and inp[r][c-1]==inp[r][c+1] and inp[r][c-1]!=0:
                o[r][c]=inp[r][c-1]
    # for each gap, fill upward from gap row-1 to 0
    for r in range(H):
        for c in range(W):
            if inp[r][c]==0 and inp[r][c-1]==inp[r][c+1] and inp[r][c-1]!=0:
                v=inp[r][c-1]
                for rr in range(r-1,-1,-1):
                    if o[rr][c]==v: break
                    if o[rr][c]==0: o[rr][c]=v
    return o
